/* Shared planning layout. Move the existing live controls; retain their handlers and permissions. */
const PlanningView=(()=>{
 let moved=[],shell=null,economyTab="map",militaryTab="map";const expanded=new Map();
 function remember(el,key,fallback=false){el.dataset.planningKey=key;el.open=expanded.get(key)??fallback;}
 const $=id=>document.getElementById(id);
 function resourceLabel(g){const label=document.createElement('span');label.className='economy-resource-label';const img=document.createElement('img');img.src='resource-icons/'+g+'.png';img.alt='';img.width=28;img.height=28;label.append(img,document.createTextNode(g));return label;}
 function move(node,parent){if(!node||!parent)return;const marker=document.createComment('planning-position');node.before(marker);moved.push([node,marker]);parent.append(node);}
 function reset(){document.querySelectorAll('[data-planning-key]').forEach(el=>expanded.set(el.dataset.planningKey,el.open));for(const [node,marker] of moved.reverse()){if(marker.parentNode)marker.replaceWith(node);}moved=[];shell?.remove();shell=null;document.body.classList.remove('planning-view');if($('goals'))$('goals').hidden=false;document.querySelector('.research-atlas')?.classList.remove('research-atlas');document.querySelectorAll('[data-planning-extra]').forEach(n=>n.remove());}
 function box(tag,cls,parent,title){const el=document.createElement(tag);el.className=cls;if(title){const h=document.createElement('h2');h.textContent=title;el.append(h);}parent?.append(el);return el;}
 function start(before){document.body.classList.add('planning-view');shell=box('section','planning-layout');shell.setAttribute('aria-label','Round planning');before.before(shell);return {left:box('div','planning-main',shell),right:box('aside','planning-sidebar',shell)};}
 function note(parent,text){const p=document.createElement('p');p.className='planning-note';p.textContent=text;parent.append(p);}
 function nav(stage,ids,callbacks={}){const overlay=box('div','planning-map-controls',stage);overlay.dataset.planningExtra='';overlay.setAttribute('aria-label','Map controls');for(const [id,label] of ids){const b=$(id);if(b){move(b,overlay);b.title=label;}}for(const [label,fn] of Object.entries(callbacks)){const b=document.createElement('button');b.type='button';b.textContent=label;b.setAttribute('aria-label',label);b.onclick=fn;overlay.append(b);}}
 function troopChoices(select,parent,types,describe){if(!select)return;select.closest('label').classList.add('planning-native-type');const grid=box('div','planning-troop-choices',parent);grid.setAttribute('role','group');grid.setAttribute('aria-label','Choose troop type');for(const [type,t] of Object.entries(types)){const option=[...select.options].find(o=>o.value===type);if(!option)continue;const b=document.createElement('button');b.type='button';b.className='planning-troop';b.disabled=select.disabled||option.disabled;const img=document.createElement('img');img.src='troop-icons/'+(type==='cavalry'?'cavalry-cutout':type)+'.png';img.alt='';const name=document.createElement('strong');name.textContent=t.name;const detail=document.createElement('small');detail.textContent=describe?describe(type):option.textContent.replace(t.name,'').replace(/^\s*[·(]\s*/,'').replace(/\)$/,'')||'Select troop';b.append(img,name,detail);b.setAttribute('aria-pressed',String(type===select.value));b.onclick=()=>{select.value=type;select.dispatchEvent(new Event('input',{bubbles:true}));select.dispatchEvent(new Event('change',{bubbles:true}));grid.querySelectorAll('button').forEach(btn=>btn.setAttribute('aria-pressed',String(btn===b)));};grid.append(b);}parent.prepend(grid);}
 function local({state,role,R}){if(state.phase!=='orders'||role!=='military')return;const toolbar=document.querySelector('.toolbar');if(toolbar){const options=box('details','planning-game-options');options.dataset.planningExtra='';toolbar.before(options);const summary=document.createElement('summary');summary.textContent='Game options · saves, worlds and other versions';options.append(summary);move(toolbar,options);}const atlas=$('map').closest('.atlas'),panel=$('decisions').closest('.panel'),{left,right}=start(atlas);move(document.querySelector('.country'),left);move(atlas,left);move(panel,left);const funds=box('section','planning-card',right,'Military resources');move($('stocks'),funds);$('stocks').innerHTML=R.goods.map(g=>'<span><strong>'+state.countries[Number($('country').value)].accounts.military[g]+'</strong> '+g+'</span>').join('');note(funds,'Available now. Troops use one food each at round-end.');const recruit=box('section','planning-card',right,'Recruit troops');const section=$('decisions').firstElementChild;move(section,recruit);const select=$('recruitType');troopChoices(select,select?.closest('.row'),R.types,type=>{const c=state.countries[Number($('country').value)];return R.goods.filter(g=>R.development.recruitCost(c,type)[g]).map(g=>R.development.recruitCost(c,type)[g]+' '+g).join(' · ')+(R.development.unlocked(c,type)?'':' · Research needed');});if(section){const row=section.querySelector('.row');if(row)section.prepend(row);const notes=[...section.children].filter(n=>n!==row);const info=box('details','planning-recruit-notes',section);const summary=document.createElement('summary');summary.textContent='Recruitment and supply rules';info.append(summary);remember(info,'recruit-rules');notes.forEach(n=>info.append(n));}if($('recruit'))$('recruit').textContent='Buy regiment';const setup=$('labSetup');if(setup){const tools=box('details','planning-card planning-setup',right);const summary=document.createElement('summary');summary.textContent='Free test army setup';tools.prepend(summary);move(setup,tools);remember(tools,'free-setup',!state.units.some(u=>u.country===Number($('country').value)));}const ready=box('section','planning-card planning-finish',right,'Finish planning');note(ready,'Review each saved order before moving everyone. Unissued orders hold position.');move($('advance'),ready);nav($('map').parentElement,[['zoomIn','Zoom in'],['zoomOut','Zoom out'],['fit','Fit map'],['panLeft','Pan west'],['panUp','Pan north'],['panDown','Pan south'],['panRight','Pan east']]);}
 function student({v,mapView,action}){if(v.phase!=='orders')return;const workspace=document.querySelector('.workspace'),atlas=$('map').closest('.card'),{left,right}=start(workspace);const identity=box('section','planning-country',left);identity.textContent=v.country.name+' · '+v.assignment.role;move(atlas,left);move($('actions'),left);move($('balances'),right);if(v.assignment.role==='military'){const recruit=box('section','planning-card',right,'Recruit troops');move($('recruit'),recruit);const form=$('recruit');troopChoices(form?.elements.kind,form,RegimentGame.types);if(form){form.querySelector('h3')?.remove();form.querySelector('button[data-write]').textContent='Buy regiment';}for(const u of v.units.filter(u=>u.country===v.country.id)){const card=$('unit-'+u.id);if(!card)continue;card.classList.add('planning-regiment');const img=document.createElement('img');img.className='planning-unit-art';img.src='troop-icons/'+(u.type==='cavalry'?'cavalry-cutout':u.type)+'.png';img.alt='';card.prepend(img);const find=document.createElement('button');find.type='button';find.className='planning-find';find.textContent='Find on map';find.onclick=()=>{mapView.focus(u.territory);atlas.scrollIntoView({behavior:'smooth',block:'start'});};card.append(find);const select=card.elements.intent;const buttons=box('div','planning-order-buttons',card);for(const [value,label] of [['move','Hold'],['capture','Capture']]){const b=document.createElement('button');b.type='button';b.dataset.write='';b.textContent=label;b.setAttribute('aria-pressed',String(select.value===value));b.onclick=()=>{select.value=value;card.requestSubmit();};buttons.append(b);}select.closest('label').classList.add('planning-native-type');}}
 const ready=box('section','planning-card planning-finish',right,'Finish planning');move($('readyArea'),ready);const tasks=box('details','planning-card',left);const summary=document.createElement('summary');summary.textContent='Your planning checklist';tasks.append(summary);move($('tasks'),tasks);move($('goals'),left);move($('summary'),left);const stage=box('div','planning-student-stage',atlas);stage.dataset.planningExtra='';move($('map'),stage);atlas.querySelector('.section-title').after(stage);nav(stage,[],{'−':()=>mapView.zoom(1.25),'+':()=>mapView.zoom(.8),'Fit':()=>mapView.fit(),'←':()=>mapView.pan(-1,0),'↑':()=>mapView.pan(0,-1),'↓':()=>mapView.pan(0,1),'→':()=>mapView.pan(1,0)});if(v.assignment.role==='military')military({v,left,right,atlas,mapView,action});
 if(v.assignment.role==='economy')economy({v,left,right,atlas,ready});
 if(v.assignment.role==='research'){
 shell.classList.add('research-layout');atlas.classList.add('research-atlas');
 const objectives=box('section','research-objectives',left,'R&D objectives');left.insertBefore(objectives,atlas);
 for(const o of v.objectives.filter(o=>o.department==='research')){const d=box('details','research-objective',objectives);remember(d,'research-objective-'+o.name);const title=document.createElement('summary');title.textContent=o.name;const meter=document.createElement('progress');meter.max=1;meter.value=o.progress;meter.setAttribute('aria-label',o.name+' progress');title.append(meter);d.append(title);note(d,o.description);note(d,o.detail+(o.done?' · Achieved':''));}
 move($('goals'),objectives);$('goals').hidden=true;move($('researchInvestment'),right);right.insertBefore($('researchInvestment'),ready);$('researchInvestment').classList.add('planning-card');
 }}
 function military({v,left,right,atlas,mapView,action}){
 shell.classList.add('military-layout');const workspace=box('section','economy-workspace',left);left.insertBefore(workspace,atlas);const tabs=box('div','economy-tabs',workspace);tabs.setAttribute('role','tablist');tabs.setAttribute('aria-label','Military views');const panels={},buttons={};
 for(const [key,title] of [['map','Map'],['objectives','Objectives'],['alliances','Alliances'],['regiments','Regiments']]){const panel=box('section','military-tab-panel',workspace);panel.id='military-panel-'+key;panel.setAttribute('role','tabpanel');panel.setAttribute('aria-label',title);panels[key]=panel;const b=document.createElement('button');b.type='button';b.setAttribute('role','tab');b.setAttribute('aria-controls',panel.id);b.textContent=title;b.onclick=()=>show(key);tabs.append(b);buttons[key]=b;}
 function show(key){militaryTab=key;for(const k of Object.keys(panels)){panels[k].hidden=k!==key;buttons[k].setAttribute('aria-selected',String(k===key));}if(key!=='map')mapView.recruitHighlight(false);}
 move(atlas,panels.map);move($('goals'),panels.objectives);const alliances=$('alliance')?.closest('details');if(alliances){move(alliances,panels.alliances);alliances.open=true;}else note(panels.alliances,'Alliance decisions appear when available.');move($('actions'),panels.regiments);
 for(const b of panels.regiments.querySelectorAll('.planning-find')){const original=b.onclick;b.onclick=()=>{show('map');original();};}
 const form=$('recruit'),picker=box('div','military-recruit-piece',form);const help=document.createElement('p');help.textContent='Choose a troop, then drag its piece onto a highlighted city. Or choose a settlement below.';picker.append(help);const piece=document.createElement('button');piece.type='button';piece.className='recruit-drag-piece';picker.append(piece);const cancel=document.createElement('button');cancel.type='button';cancel.textContent='Cancel placement';picker.append(cancel);cancel.onclick=()=>{mapView.recruitHighlight(false);piece.classList.remove('placing');};
 function choose(){const kind=form.elements.kind.value,cost=v.recruitCosts[kind],affordable=RegimentGame.goods.every(g=>v.country.accounts.military[g]>=(cost.cost[g]||0));piece.replaceChildren();const img=document.createElement('img');img.src='troop-icons/'+(kind==='cavalry'?'cavalry-cutout':kind)+'.png';img.alt='';const text=document.createElement('span');text.textContent='Drag '+RegimentGame.types[kind].name+' to a city · '+RegimentGame.goods.filter(g=>cost.cost[g]).map(g=>cost.cost[g]+' '+g).join(' · ');piece.append(img,text);piece.disabled=!cost.unlocked||!affordable||v.ready||form.querySelector('button[data-write]').disabled;piece.setAttribute('aria-label','Drag '+RegimentGame.types[kind].name+' to recruit');show('map');mapView.recruitHighlight(!piece.disabled);}
 form.elements.kind.addEventListener('change',choose);
 function confirmAt(territory){mapView.recruitHighlight(false);if(!v.recruitSites.includes(territory)){help.textContent='Drop on a highlighted friendly city. No resources were spent.';return;}const kind=form.elements.kind.value,cost=v.recruitCosts[kind].cost,dialog=document.createElement('dialog');dialog.className='tactical-finish';const h=document.createElement('h3');h.textContent='Recruit '+RegimentGame.types[kind].name+' at '+v.territories[territory].name+'?';const p=document.createElement('p');p.textContent='Cost: '+RegimentGame.goods.filter(g=>cost[g]).map(g=>cost[g]+' '+g).join(' · ')+'. Ready next year.';const yes=document.createElement('button');yes.textContent='Confirm recruitment';yes.onclick=()=>{dialog.remove();action('recruit',{kind,territory});};const no=document.createElement('button');no.textContent='Cancel';no.onclick=()=>dialog.remove();dialog.append(h,p,yes,no);dialog.addEventListener('cancel',()=>dialog.remove());document.body.append(dialog);dialog.showModal();}
 let drag=null,ghost=null;const clear=()=>{ghost?.remove();ghost=null;drag=null;piece.classList.remove('placing');};piece.onpointerdown=e=>{if(e.button!==0||piece.disabled)return;show('map');mapView.recruitHighlight(true);piece.setPointerCapture(e.pointerId);drag={id:e.pointerId,x:e.clientX,y:e.clientY,moved:false};ghost=piece.querySelector('img').cloneNode();ghost.className='recruit-drag-ghost';document.body.append(ghost);ghost.style.left=e.clientX+'px';ghost.style.top=e.clientY+'px';e.preventDefault();};piece.onpointermove=e=>{if(!drag||drag.id!==e.pointerId)return;drag.moved ||= Math.hypot(e.clientX-drag.x,e.clientY-drag.y)>5;ghost.style.left=e.clientX+'px';ghost.style.top=e.clientY+'px';};piece.onpointerup=e=>{if(!drag||drag.id!==e.pointerId)return;const moved=drag.moved,target=mapView.recruitAt(e.clientX,e.clientY);clear();if(piece.hasPointerCapture(e.pointerId))piece.releasePointerCapture(e.pointerId);if(moved)confirmAt(target);};piece.onpointercancel=()=>{clear();mapView.recruitHighlight(false);};piece.onlostpointercapture=()=>{if(drag){clear();mapView.recruitHighlight(false);}};piece.onclick=()=>{show('map');mapView.recruitHighlight(true);help.textContent='Drag this piece onto a highlighted city, or use the settlement selector below.';};
 const previousTab=militaryTab;choose();show(previousTab);mapView.recruitHighlight(false);
 }
 function reserveForecast(v,plan){
  const c=v.country,goods=['money','food','wood','metal'],own=v.territories.filter(t=>t.owner===c.id),civilianNeed=own.reduce((n,t)=>n+t.foodNeed,0),armyNeed=v.units.filter(u=>u.country===c.id&&u.hp>0).length;
  const resources=goods.map(g=>{const available=c.stock[g]+c.allocations.military[g]+c.allocations.research[g],military=plan.military[g],research=plan.research[g],retained=available-military-research,required=g==='food'?civilianNeed:0,income=own.reduce((n,t)=>n+(t.output?.[g]||0),0);return {good:g,available,military,research,retained,required,income,shortfall:Math.max(0,required-retained),spare:Math.max(0,retained-required),projected:retained-Math.min(Math.max(0,retained),required)+income};});
  const armyFood=c.accounts.military.food+plan.military.food;
  return {resources,civilianNeed,armyNeed,armyFood,armyDeliveryNeeded:Math.max(0,armyNeed-c.accounts.military.food),armyShortfall:Math.max(0,armyNeed-armyFood)};
 }
 function economy({v,left,right,atlas,ready}){
  shell.classList.add('economy-layout');const c=v.country,goods=RegimentGame.goods,own=v.territories.filter(t=>t.owner===c.id),need=own.reduce((n,t)=>n+t.foodNeed,0);
  const workspace=box('section','economy-workspace');left.insertBefore(workspace,atlas);const tabs=box('div','economy-tabs',workspace);tabs.setAttribute('role','tablist');tabs.setAttribute('aria-label','Economy views');
  const panels={},buttons={};for(const [key,title] of [['map','Map'],['income','Income'],['objectives','Objectives'],['trade','Trade offers'],['buy','Buy']]){const panel=box('section','economy-tab-panel',workspace);panel.id='economy-panel-'+key;panel.setAttribute('role','tabpanel');panels[key]=panel;const button=document.createElement('button');button.type='button';button.id='economy-tab-'+key;button.setAttribute('role','tab');button.setAttribute('aria-controls',panel.id);panel.setAttribute('aria-labelledby',button.id);const pending=v.exchanges.filter(o=>o.to===c.id&&o.status==='pending').length,done=v.objectives.filter(o=>o.department==='economy'&&o.done).length;button.textContent=title+(key==='trade'&&pending?' ('+pending+')':key==='objectives'?' ('+done+'/'+v.objectives.filter(o=>o.department==='economy').length+')':key==='buy'?' ('+Object.values(RegimentGame.development.improvements).filter(f=>RegimentGame.development.has(c,f.tech)).length+' unlocked)':'');button.onclick=()=>show(key);tabs.append(button);buttons[key]=button;}
  function show(key){economyTab=key;for(const k of Object.keys(panels)){panels[k].hidden=k!==key;buttons[k].setAttribute('aria-selected',String(k===key));buttons[k].tabIndex=k===key?0:-1;}}
  tabs.onkeydown=e=>{const keys=Object.keys(buttons),i=keys.indexOf(economyTab);let next;if(e.key==='ArrowRight')next=keys[(i+1)%keys.length];if(e.key==='ArrowLeft')next=keys[(i+keys.length-1)%keys.length];if(e.key==='Home')next=keys[0];if(e.key==='End')next=keys.at(-1);if(next){e.preventDefault();show(next);buttons[next].focus();}};
  move(atlas,panels.map);move($('goals'),panels.objectives);const trade=$('exchange')?.closest('details');if(trade){move(trade,panels.trade);trade.open=true;}
  const allocation=box('section','planning-card economy-distribution',left,'Distribute resources');left.insertBefore(allocation,workspace.nextSibling);move($('allocations'),allocation);move($('actions'),panels.buy);
  note(panels.income,'Expected production at year-end. This income is not available to allocate or spend yet.');const table=document.createElement('table');const head=table.createTHead().insertRow();for(const label of ['Resource','Expected production']){const th=document.createElement('th');th.textContent=label;head.append(th);}const body=table.createTBody();for(const g of goods){const row=body.insertRow();row.insertCell().append(resourceLabel(g));row.insertCell().textContent=own.reduce((n,t)=>n+(t.output?.[g]||0),0);}panels.income.append(table);note(panels.income,need+' food needed for civilians. Military meals come from the Military account after deliveries.');
  const balances=$('balances');balances.replaceChildren();const title=document.createElement('h2');title.textContent='Current resources';balances.append(title);const state=box('p','economy-save-state',balances),budget=document.createElement('table');budget.setAttribute('aria-label','Allocation budget');const heading=budget.createTHead().insertRow();for(const label of ['Resource','Available','Allocated','Remaining']){const th=document.createElement('th');th.textContent=label;heading.append(th);}const rows={},tbody=budget.createTBody();for(const g of goods){const row=tbody.insertRow();rows[g]=[row.insertCell(),row.insertCell(),row.insertCell(),row.insertCell()];rows[g][0].append(resourceLabel(g));}balances.append(budget);const reserve=box('p','',balances);note(balances,'Available includes saved allocations, which you can redistribute. Deliveries arrive at year-end.');const review=box('div','economy-review',ready);ready.insertBefore(review,ready.firstChild.nextSibling);
  const forecast=box('section','economy-forecast',panels.income,'Save for year-end');forecast.setAttribute('aria-label','Year-end resource forecast');const foodGuide=box('section','economy-food-guide',balances,'Food to keep');
  const form=$('allocations'),pool=Object.fromEntries(goods.map(g=>[g,c.stock[g]+c.allocations.military[g]+c.allocations.research[g]]));
  function renderForecast(){const plan=Object.fromEntries(['military','research'].map(d=>[d,Object.fromEntries(goods.map(g=>[g,Math.max(0,Number(form.elements[d+'-'+g].value)||0)]))])),f=reserveForecast(v,plan);forecast.replaceChildren();const h=document.createElement('h3');h.textContent='Save for year-end';forecast.append(h);note(forecast,'Your current supplies: department deliveries, civilian reserve, and spare Treasury supplies. Expected income arrives later.');
   const legend=box('div','reserve-legend',forecast);for(const [key,label] of [['military','Military delivery'],['research','R&D delivery'],['required','Keep for civilians'],['spare','Spare Treasury']]){const item=box('span','reserve-key '+key,legend);item.textContent=label;}
   for(const r of f.resources){const row=box('article','reserve-resource',forecast);const title=box('div','reserve-title',row);title.append(resourceLabel(r.good));const total=document.createElement('strong');total.textContent=r.available+' available now';title.append(total);const bar=box('div','reserve-bar',row);bar.setAttribute('role','img');bar.setAttribute('aria-label',`${r.good}: ${r.military} Military, ${r.research} R&D, ${Math.min(r.required,Math.max(0,r.retained))} reserved for civilians, ${r.spare} spare`);for(const [key,value] of [['military',r.military],['research',r.research],['required',Math.min(r.required,Math.max(0,r.retained))],['spare',r.spare]]){if(value<=0)continue;const part=box('span',key,bar);part.style.width=(100*value/Math.max(1,r.available))+'%';part.textContent=value;part.title=value+' '+legend.querySelector('.'+key).textContent;}note(row,`Keep ${r.required} for civilian needs · ${r.spare} spare · Expected income +${r.income} · Estimated Treasury after meals and income: ${r.projected}`);if(r.shortfall){const warning=box('p','warning',row);warning.textContent=`Short by ${r.shortfall} food for civilians. Reduce allocations or obtain food before feeding; future income cannot cover this meal.`;}}
   foodGuide.replaceChildren();const heading=document.createElement('h3');heading.textContent='Food to keep';foodGuide.append(heading);for(const [label,held,need] of [['Civilian reserve in Treasury',f.resources.find(r=>r.good==='food').retained,f.civilianNeed],['Army food after delivery',f.armyFood,f.armyNeed]]){const group=box('div','food-coverage',foodGuide);const text=box('p',held<need?'warning':'good',group);text.textContent=`${label}: ${held} / ${need} needed` ;const meter=document.createElement('meter');meter.min=0;meter.max=Math.max(1,need);meter.value=Math.max(0,Math.min(held,meter.max));meter.setAttribute('aria-label',label);group.append(meter);}
   note(foodGuide,`Allocate at least ${f.armyDeliveryNeeded} food to Military for the current army. ${f.armyShortfall?'Army shortfall: '+f.armyShortfall+'.':'Current army meals are covered.'}`);note(forecast,'Estimate based on current land and living regiments, including trainees. Battles, recruitment, trade and changes in happiness can change these totals. Army meals use the Military account after deliveries.');
  }
  function update(){let changed=false;const sums={military:[],research:[]};for(const g of goods){let total=0;for(const d of ['military','research']){const input=form.elements[d+'-'+g],other=form.elements[(d==='military'?'research':'military')+'-'+g];input.max=Math.max(0,pool[g]-(Number(other.value)||0));const n=Number(input.value)||0;total+=n;changed ||= n!==c.allocations[d][g];sums[d].push(n+' '+g);}rows[g][1].textContent=pool[g];rows[g][2].textContent=total;rows[g][3].textContent=pool[g]-total;rows[g][3].className=pool[g]<total?'warning':'';}state.textContent=changed?'Unsaved allocation changes':'Allocations saved';state.className='economy-save-state '+(changed?'warning':'good');const remaining=pool.food-(Number(form.elements['military-food'].value)||0)-(Number(form.elements['research-food'].value)||0);reserve.textContent='Civilian food: '+remaining+' retained / '+need+' needed';reserve.className=remaining<need?'warning':'good';review.replaceChildren();note(review,'Military: '+sums.military.join(' · '));note(review,'R&D: '+sums.research.join(' · '));note(review,reserve.textContent);note(review,changed?'Save department funding before marking ready.':'Review these saved allocations, then mark ready.');renderForecast();}
  for(const input of form.querySelectorAll('input')){const label=input.closest('label');if(!label.querySelector('.economy-resource-label')){const text=[...label.childNodes].find(n=>n.nodeType===3&&n.textContent.trim());if(text)text.replaceWith(resourceLabel(input.name.split('-').pop()));}input.setAttribute('aria-label',input.name.replace('research','R&D').replace('-',' '));const wrap=box('span','economy-stepper');input.before(wrap);wrap.append(input);for(const [label,delta] of [['−',-1],['+',1]]){const button=document.createElement('button');button.type='button';button.dataset.write='';button.textContent=label;button.setAttribute('aria-label',(delta<0?'Decrease ':'Increase ')+input.name.replace('research','R&D').replace('-',' '));button.onclick=()=>{input.value=Math.max(0,Math.min(Number(input.max),Number(input.value)+delta));input.dispatchEvent(new Event('input',{bubbles:true}));};delta<0?wrap.prepend(button):wrap.append(button);}}
  form.addEventListener('input',e=>{if(e.target.matches('input')){const input=e.target;if(Number(input.value)>Number(input.max))input.value=input.max;if(Number(input.value)<0)input.value=0;}update();});update();show(economyTab);
 }
 function online({view,R,focus}){if(view.game.phase!=='orders')return;const atlas=$('map').closest('.atlas'),{left,right}=start($('controls'));move(document.querySelector('#game .country'),left);move(atlas,left);move($('controls'),left);const funds=box('section','planning-card',right,'Military resources');move($('funds'),funds);const recruit=box('section','planning-card',right,view.setup?'Build your test army':'Recruit troops');const form=$(view.setup?'addForm':'recruitForm');move(form,recruit);const select=$(view.setup?'troopType':'recruitType');troopChoices(select,form,R.types);if(form)form.querySelector('button.primary,button[type=submit],button:not([type])').textContent=view.setup?'Add test troops':'Buy regiment';if(view.setup){note(recruit,'Free setup: choose troop, health, equipment and starting land.');const extra=box('details','planning-card',right);const summary=document.createElement('summary');summary.textContent='More setup controls';extra.append(summary);remember(extra,'online-setup',true);move($('moveForm'),extra);move($('clearArmy'),extra);}const ready=box('section','planning-card planning-finish',right,'Finish planning');move($('readiness'),ready);move($('ready'),ready);move($('discard'),ready);for(const u of view.game.units.filter(u=>u.hp>0&&u.country===view.player)){const card=$('order-'+u.id)?.closest('.regiment')||document.querySelector(`[data-remove="${u.id}"]`)?.closest('.regiment');if(!card)continue;const b=document.createElement('button');b.type='button';b.textContent='Find on map';b.onclick=()=>{focus(u.territory);atlas.scrollIntoView({behavior:'smooth',block:'start'});};card.append(b);const intent=$('intent-'+u.id);if(intent){const row=box('div','planning-order-buttons',card);for(const [value,label] of [['move','Hold'],['capture','Capture']]){const button=document.createElement('button');button.type='button';button.textContent=label;button.disabled=intent.disabled;button.setAttribute('aria-pressed',String(intent.value===value));button.onclick=()=>{intent.value=value;$('order-'+u.id).requestSubmit();};row.append(button);}intent.closest('label').classList.add('planning-native-type');}}nav($('map').parentElement,[['zoomIn','Zoom in'],['zoomOut','Zoom out'],['fit','Fit map'],['find','Find my kingdom']]);}
 function simulation({phase,map,controls,identity,next}){if(phase!=='movement'||!map||!controls)return;const {left,right}=start(map.closest('.workspace')||map);if(identity)move(identity,left);move(map,left);if(next)move(next,left);move(controls,left);right.remove();shell.classList.add('movement-layout');shell.setAttribute('aria-label','Movement simulation');}
 // Every phase gets the same on-map controls and a readable details rail.
 function mapUI({kind='local',mapView}={}){
  const canvas=$('map');if(!canvas)return;
  let stage=canvas.closest('.map-stage,.planning-student-stage');
  if(!stage){stage=box('div','planning-student-stage');stage.dataset.planningExtra='';canvas.before(stage);move(canvas,stage);}
  if(!stage.querySelector('.planning-map-controls')){
   if(kind==='student')nav(stage,[],{'−':()=>mapView.zoom(1.25),'+':()=>mapView.zoom(.8),'Fit':()=>mapView.fit(),'←':()=>mapView.pan(-1,0),'↑':()=>mapView.pan(0,-1),'↓':()=>mapView.pan(0,1),'→':()=>mapView.pan(1,0)});
   else nav(stage,kind==='online'?[['zoomIn','Zoom in'],['zoomOut','Zoom out'],['fit','Fit map'],['find','Find my kingdom']]:[['zoomIn','Zoom in'],['zoomOut','Zoom out'],['fit','Fit map'],['panLeft','Pan west'],['panUp','Pan north'],['panDown','Pan south'],['panRight','Pan east']]);
  }
  if(kind==='online'&&mapView){const overlay=stage.querySelector('.planning-map-controls');for(const [label,x,y] of [['←',-1,0],['↑',0,-1],['↓',0,1],['→',1,0]]){const b=document.createElement('button');b.type='button';b.textContent=label;b.setAttribute('aria-label',{'←':'Pan west','↑':'Pan north','↓':'Pan south','→':'Pan east'}[label]);b.onclick=()=>mapView.pan(x,y);overlay.append(b);}}
  const wrap=box('div','map-reading-layout');wrap.dataset.planningExtra='';stage.before(wrap);move(stage,wrap);
  const rail=box('aside','map-details-rail',shell?.classList.contains('research-layout')?shell.querySelector('.planning-sidebar'):wrap);rail.setAttribute('aria-label','Map details');
  const select=$(kind==='student'?'mapTerritory':kind==='online'?'inspect':'territory');if(select)move(select.closest('label'),rail);
  move($(kind==='student'?'territoryDetail':'territoryInfo'),rail);if(kind==='local')move($('territoryPopup'),rail);
 }
 // Reparenting the map and controls temporarily changes document height.
 // Restore once the synchronous render is complete; intentional Find navigation follows it.
 function preserveScroll(){const x=window.scrollX,y=window.scrollY;return ()=>window.scrollTo({left:x,top:y,behavior:'instant'});}
 return {reset,local,student,online,simulation,mapUI,preserveScroll,reserveForecast};
})();

if(typeof module==='object')module.exports=PlanningView;
